            <el-table :data="quoteLines"><el-table-column prop="supplierQuoteNo" label="报价编号" width="180"/><el-table-column prop="supplierName" label="供应商" min-width="180"/><el-table-column label="产品行" width="90"><template #default="{row}">#{{ sourceLineNo(row.sourcingLineId) }}</template></el-table-column><el-table-column label="报价" width="150"><template #default="{row}">{{ row.currency }} {{ row.unitPrice }}</template></el-table-column><el-table-column prop="leadTime" label="交期"/><el-table-column prop="validUntil" label="有效期" width="130"/></el-table>
